/*
<Group description="Fundo e Cores Base" selector="body">
  <Variable name="body.background" description="Fundo Geral" type="background" color="#f8fafc" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
  <Variable name="main.color" description="Cor Principal" type="color" default="#6366f1" value="#6366f1"/>
  <Variable name="theme.text" description="Cor do Texto" type="color" default="#1e293b" value="#1e293b"/>
  <Variable name="header.bg" description="Fundo do Cabeçalho" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.bg" description="Fundo do Rodapé" type="color" default="#1e293b" value="#1e293b"/>
</Group>
<Group description="Tipografia" selector="body">
  <Variable name="body.font" description="Fonte do Texto" type="font" default="normal normal 16px system-ui,-apple-system,sans-serif" value="normal normal 16px system-ui,-apple-system,sans-serif"/>
</Group>
*/

:root {
  --sl-bg-body:        $(body.background);
  --sl-text-main:      $(theme.text);
  --sl-primary:        $(main.color);
  --sl-card-bg:        #ffffff;
  --sl-footer-bg:      #1e293b;
  --sl-radius-lg:      14px;
  --sl-radius-sm:      7px;
  --sl-transition:     all 0.3s cubic-bezier(0.4,0,0.2,1);
  --sl-btn-radius:     8px;
  --sl-btn-shadow:     0 2px 6px rgba(0,0,0,0.15);
  --sl-font-family:    system-ui,-apple-system,sans-serif;
  --sl-heading-weight: 700;
}

[[DYNAMIC_CSS]]

body {
  background-color: var(--sl-bg-body,#f8fafc);
  color: var(--sl-text-main);
  font-family: var(--sl-font-family,system-ui,sans-serif);
  margin:0; padding:0; overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
img { max-width:100%; height:auto; display:block; }
a { color:var(--sl-primary); text-decoration:none; transition:var(--sl-transition); }
a:hover { filter:brightness(0.85); }
h1,h2,h3,h4,h5,h6 { font-weight:var(--sl-heading-weight); }

/* ── HEADER ─────────────────────────────────────────── */
.sl-header {
  background: var(--sl-card-bg);
  border-bottom: 1px solid rgba(0,0,0,0.07);
  padding: .875rem 0;
}
.sl-header-brand { font-size:1.4rem; font-weight:800; color:var(--sl-text-main); letter-spacing:-.02em; }
.sl-header-brand:hover { color:var(--sl-primary); filter:none; }
.sl-header-search { max-width:260px; }
@media (max-width:575.98px) { .sl-header-search { display:none !important; } }

/* ── NAV ─────────────────────────────────────────────── */
.sl-nav {
  background: var(--sl-primary);
  padding: 0;
}
.sl-nav ul { list-style:none; padding:0; margin:0; display:flex; flex-wrap:wrap; }
.sl-nav ul li { position:relative; }
.sl-nav ul li a {
  display:block; padding:10px 16px;
  color:rgba(255,255,255,0.9); font-size:.875rem; font-weight:600;
  transition:var(--sl-transition);
}
.sl-nav ul li a:hover { background:rgba(0,0,0,0.15); color:#fff; filter:none; }
.sl-nav ul ul {
  position:absolute; top:100%; left:0; display:none;
  background:var(--sl-card-bg); min-width:200px;
  box-shadow:0 10px 25px rgba(0,0,0,0.15); z-index:99;
  border-radius:0 0 var(--sl-radius-sm) var(--sl-radius-sm);
}
.sl-nav ul ul li a { color:var(--sl-text-main); padding:9px 16px; }
.sl-nav ul ul li a:hover { background:color-mix(in srgb,var(--sl-primary) 8%,transparent); color:var(--sl-primary); }
.sl-nav ul li:hover > ul { display:block; }
@media (max-width:768px) {
  .sl-nav ul ul { position:static; box-shadow:none; background:rgba(0,0,0,0.15); }
  .sl-nav ul ul li a { color:rgba(255,255,255,.9); }
}

/* ── CATEGORY FILTER BAR ─────────────────────────────── */
.blog-cat-bar-wrapper {
  background: var(--sl-card-bg);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.blog-cat-bar-wrapper::-webkit-scrollbar { display:none; }
.blog-cat-bar {
  display: flex;
  gap: 6px;
  padding: 10px 0;
  white-space: nowrap;
  min-width: max-content;
}
.blog-cat-btn {
  display: inline-block;
  padding: 5px 14px;
  border-radius: 50px;
  font-size: .8rem;
  font-weight: 700;
  color: var(--sl-text-main);
  background: transparent;
  border: 1.5px solid rgba(0,0,0,0.12);
  transition: var(--sl-transition);
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
}
.blog-cat-btn:hover,
.blog-cat-btn.active {
  background: var(--sl-primary);
  color: #fff;
  border-color: var(--sl-primary);
  filter: none;
}

/* ── FEATURED CARD (1º POST) ─────────────────────────── */
.blog-featured {
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: var(--sl-radius-lg);
  overflow: hidden;
  transition: var(--sl-transition);
  margin-bottom: 1.5rem;
  display: flex;
  flex-direction: row;
}
@media (min-width:992px) {
  .blog-featured:hover { box-shadow:0 20px 35px -5px rgba(0,0,0,0.1); transform:translateY(-2px); }
}
.blog-featured-thumb {
  width: 45%;
  flex-shrink: 0;
  overflow: hidden;
}
.blog-featured-thumb img {
  width: 100%; height: 100%;
  object-fit: cover; display: block;
  min-height: 240px;
  transition: transform .5s ease;
}
.blog-featured:hover .blog-featured-thumb img { transform:scale(1.04); }
.blog-featured-body {
  flex: 1;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.blog-featured-tag {
  display: inline-block;
  background: color-mix(in srgb,var(--sl-primary) 12%,transparent);
  color: var(--sl-primary);
  padding: 3px 12px; border-radius:50px;
  font-size:.75rem; font-weight:800;
  text-transform:uppercase; letter-spacing:.06em;
  margin-bottom:.75rem;
  text-decoration:none;
}
.blog-featured-tag:hover { background:var(--sl-primary); color:#fff; filter:none; }
.blog-featured-title { font-size:1.4rem; line-height:1.3; margin-bottom:.75rem; font-weight:800; }
.blog-featured-title a { color:var(--sl-text-main); }
.blog-featured-title a:hover { color:var(--sl-primary); filter:none; }
.blog-featured-snippet { color:#64748b; font-size:.9rem; line-height:1.65; margin-bottom:1rem; display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; }
.blog-featured-meta { display:flex; align-items:center; gap:1rem; font-size:.8rem; color:#94a3b8; flex-wrap:wrap; }
@media (max-width:767.98px) {
  .blog-featured { flex-direction:column; }
  .blog-featured-thumb { width:100%; }
  .blog-featured-thumb img { min-height:200px; max-height:220px; }
  .blog-featured-body { padding:1.25rem; }
  .blog-featured-title { font-size:1.15rem; }
}

/* ── NEWS CARDS (GRID) ───────────────────────────────── */
.news-card {
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: var(--sl-radius-lg);
  overflow: hidden;
  transition: var(--sl-transition);
}
@media (min-width:992px) {
  .news-card:hover { transform:translateY(-4px); box-shadow:0 16px 30px -5px rgba(0,0,0,0.1); }
}
.news-card p.text-muted {
  display:-webkit-box;
  -webkit-line-clamp:3;
  -webkit-box-orient:vertical;
  overflow:hidden;
}
.news-card-img {
  width:100%; aspect-ratio:16/9;
  object-fit:cover; display:block;
  transition:transform .4s ease;
}
.news-card:hover .news-card-img { transform:scale(1.04); }

/* ── SIDEBAR WIDGETS ─────────────────────────────────── */
.blog-widget {
  background: var(--sl-card-bg);
  border: 1px solid rgba(0,0,0,0.06);
  border-radius: var(--sl-radius-lg);
  overflow: hidden;
  margin-bottom: 1.5rem;
}
.blog-widget-header {
  padding: 12px 16px;
  font-weight: 800;
  font-size: .75rem;
  text-transform: uppercase;
  letter-spacing: .09em;
  border-bottom: 1px solid rgba(0,0,0,0.06);
  display: flex; align-items:center; gap:8px;
}
.blog-widget-header::before { content:''; width:3px; height:14px; background:var(--sl-primary); border-radius:2px; }
.blog-widget-body { padding:14px 16px; }

/* Author card */
.blog-author-widget .blog-author-img {
  width:72px; height:72px;
  border-radius:50%; object-fit:cover;
  border:3px solid color-mix(in srgb,var(--sl-primary) 20%,transparent);
}
.blog-author-widget a { color:var(--sl-primary); font-size:.82rem; font-weight:700; }
.blog-author-widget a:hover { filter:brightness(.85); }

/* Popular posts list */
.blog-popular-list { list-style:none; padding:0; margin:0; }
.blog-popular-list li {
  display:flex; gap:10px; align-items:center;
  padding:9px 0;
  border-bottom:1px solid rgba(0,0,0,0.05);
}
.blog-popular-list li:last-child { border-bottom:none; }
.blog-popular-list .blog-pop-thumb {
  width:56px; height:42px; flex-shrink:0;
  border-radius:var(--sl-radius-sm); overflow:hidden;
}
.blog-popular-list .blog-pop-thumb img { width:100%; height:100%; object-fit:cover; }
.blog-popular-list a { color:var(--sl-text-main); font-size:.82rem; font-weight:600; line-height:1.3; }
.blog-popular-list a:hover { color:var(--sl-primary); filter:none; }

/* Label pills */
.sl-label-widget ul { padding:0; margin:0; list-style:none; display:flex; flex-wrap:wrap; gap:7px; }
.sl-label-list a {
  display:inline-block; padding:5px 13px;
  background:color-mix(in srgb,var(--sl-primary) 10%,transparent);
  color:var(--sl-primary); border-radius:50px;
  font-size:.8rem; font-weight:700; transition:var(--sl-transition);
}
.sl-label-list a:hover { background:var(--sl-primary); color:#fff; filter:none; }
.sl-label-cloud a {
  display:inline-block; padding:4px 12px;
  border:1px solid var(--sl-primary); color:var(--sl-text-main);
  border-radius:var(--sl-radius-lg); font-size:.88rem; transition:var(--sl-transition);
}
.sl-label-cloud a:hover { background:var(--sl-primary); color:#fff; transform:translateY(-2px); filter:none; }

/* ── AUTO-TOC (single post sidebar) ─────────────────── */
.blog-toc-widget { position:sticky; top:16px; }
.blog-toc-list { list-style:none; padding:0; margin:0; }
.blog-toc-list li { border-left:2px solid rgba(0,0,0,0.08); padding:.25rem 0 .25rem .75rem; transition:border-color .2s; }
.blog-toc-list li.active { border-left-color:var(--sl-primary); }
.blog-toc-list li.toc-h3 { padding-left:1.25rem; font-size:.8rem; }
.blog-toc-list a { color:#64748b; font-size:.83rem; line-height:1.4; display:block; }
.blog-toc-list a:hover,.blog-toc-list li.active a { color:var(--sl-primary); filter:none; }

/* ── SINGLE POST TYPOGRAPHY ──────────────────────────── */
.blog-post-hero { border-radius:var(--sl-radius-lg); overflow:hidden; margin-bottom:1.75rem; }
.blog-post-hero img { width:100%; aspect-ratio:16/9; object-fit:cover; display:block; }
.blog-post-meta {
  display:flex; flex-wrap:wrap; gap:.85rem;
  padding:.7rem 0; margin-bottom:1.5rem;
  border-top:1px solid rgba(0,0,0,0.07);
  border-bottom:1px solid rgba(0,0,0,0.07);
  font-size:.85rem; color:#64748b;
}
.blog-post-meta a { color:#64748b; }
.blog-post-meta a:hover { color:var(--sl-primary); filter:none; }
.blog-post-body { font-size:1.06rem; line-height:1.85; }
.blog-post-body h2 { margin-top:2.5rem; padding-bottom:.5rem; border-bottom:2px solid rgba(0,0,0,0.07); }
.blog-post-body h3 { margin-top:2rem; }
.blog-post-body p { margin-bottom:1.4rem; }
.blog-post-body img { border-radius:var(--sl-radius-sm); margin:1rem auto; }
.blog-post-body a { text-decoration:underline; text-decoration-color:color-mix(in srgb,var(--sl-primary) 50%,transparent); text-underline-offset:3px; }
.blog-post-body iframe,.blog-post-body object,.blog-post-body embed { max-width:100%; }
.blog-post-body blockquote {
  margin:2rem 0; padding:1.5rem 1.75rem;
  background:color-mix(in srgb,var(--sl-primary) 5%,transparent);
  border-left:5px solid var(--sl-primary);
  border-radius:0 var(--sl-radius-lg) var(--sl-radius-lg) 0;
  font-style:italic; font-size:1.1rem; line-height:1.65;
}
.blog-post-body blockquote p { margin-bottom:0; }

/* ── SHARE / AUTHOR / RELATED ─────────────────────────── */
.sl-share-buttons a.btn { flex-shrink:0; }
.sl-author-box { border:1px solid rgba(0,0,0,0.06) !important; border-radius:var(--sl-radius-lg); box-shadow:0 4px 6px -1px rgba(0,0,0,0.05); }
.sl-related-posts .news-card { height:100%; }
.sl-related-posts .news-card img { width:100%; aspect-ratio:16/9; object-fit:cover; }

/* ── BUTTONS ──────────────────────────────────────────── */
.btn-primary,.btn-outline-primary { border-radius:var(--sl-btn-radius); box-shadow:var(--sl-btn-shadow); }
.btn-outline-primary { color:var(--sl-primary); border-color:var(--sl-primary); }
.btn-outline-primary:hover,.btn-outline-primary:focus,.btn-outline-primary:active,.btn-outline-primary.active {
  background-color:var(--sl-primary); border-color:var(--sl-primary); color:#fff; filter:none;
}

/* ── FOOTER ───────────────────────────────────────────── */
.sl-footer { background:var(--sl-footer-bg,#1e293b); color:#94a3b8; }
.sl-footer h6 { color:#f1f5f9; font-weight:700; text-transform:uppercase; letter-spacing:.06em; font-size:.75rem; margin-bottom:1rem; }
.sl-footer a { color:#94a3b8; font-size:.875rem; }
.sl-footer a:hover { color:#f1f5f9; filter:none; }
.sl-footer-divider { border-color:rgba(255,255,255,0.08) !important; }

/* ── DARK MODE ────────────────────────────────────────── */
[data-bs-theme="dark"] body { background-color:#0d1117; color:#e2e8f0; }
[data-bs-theme="dark"] .sl-header { background:#161c2d; border-bottom-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .sl-header-brand { color:#e2e8f0; }
[data-bs-theme="dark"] .blog-cat-bar-wrapper { background:#161c2d; border-bottom-color:rgba(255,255,255,0.07); }
[data-bs-theme="dark"] .blog-cat-btn { color:#cbd5e1; border-color:rgba(255,255,255,0.12); }
[data-bs-theme="dark"] .blog-featured,
[data-bs-theme="dark"] .news-card,
[data-bs-theme="dark"] .blog-widget { background:#1e2535; border-color:rgba(255,255,255,0.06); }
[data-bs-theme="dark"] .blog-featured-title a { color:#e2e8f0; }
[data-bs-theme="dark"] .blog-featured-snippet { color:#94a3b8; }
[data-bs-theme="dark"] .blog-popular-list li { border-bottom-color:rgba(255,255,255,0.06); }
[data-bs-theme="dark"] .blog-toc-list li { border-left-color:rgba(255,255,255,0.1); }
[data-bs-theme="dark"] .blog-post-meta { border-color:rgba(255,255,255,0.07); color:#94a3b8; }
[data-bs-theme="dark"] .blog-post-meta a { color:#94a3b8; }
[data-bs-theme="dark"] .blog-post-body h2 { border-bottom-color:rgba(255,255,255,0.08); }
[data-bs-theme="dark"] .sl-author-box { border-color:rgba(255,255,255,0.06) !important; background:#1e2535; }
[data-bs-theme="dark"] .blog-post-article { background:#1e2535 !important; }
[data-bs-theme="dark"] .blog-widget-header { background:rgba(255,255,255,0.04); border-bottom-color:rgba(255,255,255,0.07); }

/* ── RESPONSIVE ────────────────────────────────────────── */
@media (max-width:575.98px) {
  .blog-featured-title { font-size:1.05rem; }
  .blog-featured-body { padding:1rem; }
  .blog-post-body { font-size:.97rem; }
}

/* GRID LAYOUTS (lista/dupla/revista/quadrado/mural/coluna-unica/zigzag) —
   centralizado em gerarGridCardCss() (designTokensCss.js), injetado via
   DYNAMIC_CSS. Removido daqui pra não duplicar/divergir entre chassis. */

