  (function(){

    // ── Category filter bar ───────────────────────────────
    var catBar = document.getElementById('blog-cat-bar');
    if (catBar) {
      var currentLabel = '';
      var labelMatch = window.location.pathname.match(/\/search\/label\/([^/?]+)/);
      if (labelMatch) currentLabel = decodeURIComponent(labelMatch[1]);

      fetch('/feeds/posts/default?alt=json&max-results=20&fields=feed/entry/category')
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(data){
          if (!data || !data.feed || !data.feed.entry) return;
          var seen = {};
          var cats = [];
          data.feed.entry.forEach(function(e){
            (e.category || []).forEach(function(c){
              if (!seen[c.term]) { seen[c.term] = true; cats.push(c.term); }
            });
          });
          cats.sort();
          var html = '<a class="blog-cat-btn'+(currentLabel===''?' active':'')+'" href="/">Todos</a>';
          cats.forEach(function(c){
            html += '<a class="blog-cat-btn'+(c===currentLabel?' active':'')+'" href="/search/label/'+encodeURIComponent(c)+'">'+c+'</a>';
          });
          catBar.innerHTML = html;
        })
        .catch(function(){ if(catBar.parentElement) catBar.parentElement.style.display='none'; });
    }

    // ── Popular posts sidebar ─────────────────────────────
    var popList = document.getElementById('blog-popular-list');
    if (popList) {
      fetch('/feeds/posts/default?alt=json&max-results=5&orderby=published')
        .then(function(r){ return r.ok ? r.json() : null; })
        .then(function(data){
          if (!data || !data.feed || !data.feed.entry) return;
          popList.innerHTML = data.feed.entry.map(function(e){
            var lnk = (e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
            var url = lnk ? lnk.href : '#';
            var title = (e.title||{}).$t || '';
            var raw = (e.media$thumbnail||{}).url || '';
            var thumb = raw ? raw.replace(/\/s[\d]+-c(\/|$)/,'/s80-c/') : '[[PLACEHOLDER_IMG]]';
            return '<li>'
              + '<div class="blog-pop-thumb"><img loading="lazy" src="'+thumb+'" alt="'+title+'"/></div>'
              + '<div><a href="'+url+'">'+title+'</a></div>'
              + '</li>';
          }).join('');
        })
        .catch(function(){
          var w = popList.closest('#blog-popular-widget');
          if (w) w.style.display = 'none';
        });
    }

    // ── Auto-TOC (single post only) ────────────────────────
    var tocList = document.getElementById('blog-toc-list');
    var postBody = document.getElementById('blog-post-body-content');
    if (tocList && postBody) {
      var headings = postBody.querySelectorAll('h2,h3');
      if (headings.length < 2) {
        var tw = document.getElementById('blog-toc-widget');
        if (tw) tw.style.display = 'none';
      } else {
        var items = [];
        headings.forEach(function(h, idx){
          var id = 'toc-h-' + idx;
          h.id = id;
          var isH3 = h.tagName === 'H3';
          items.push('<li class="'+(isH3?'toc-h3':'')+'"><a href="#'+id+'">'+h.textContent+'</a></li>');
        });
        tocList.innerHTML = items.join('');

        // Highlight active heading on scroll
        var tocItems = tocList.querySelectorAll('li');
        var headingIds = Array.from(headings).map(function(h){ return h.id; });
        var observer = new IntersectionObserver(function(entries){
          entries.forEach(function(entry){
            if (entry.isIntersecting) {
              var idx = headingIds.indexOf(entry.target.id);
              if (idx >= 0) {
                tocItems.forEach(function(li){ li.classList.remove('active'); });
                tocItems[idx] && tocItems[idx].classList.add('active');
              }
            }
          });
        }, { rootMargin:'-20% 0px -70% 0px' });
        headings.forEach(function(h){ observer.observe(h); });
      }
    }

  })();
  //





  //
  (function(){
    var grid = document.getElementById('sl-related-ready');
    if (!grid) return;
    function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
    var label      = (document.getElementById('sl-post-label')||{}).textContent.trim();
    var currentUrl = (document.getElementById('sl-post-url')  ||{}).textContent.trim();
    if (!label) { var rp=grid.closest('.sl-related-posts'); if(rp) rp.style.display='none'; return; }
    fetch('/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results=4')
      .then(function(r){ if(!r.ok) throw 0; return r.json(); })
      .then(function(data){
        var entries=(data.feed.entry||[]).filter(function(e){
          var l=(e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
          return l && l.href!==currentUrl;
        }).slice(0,3);
        if(!entries.length){ var rp2=grid.closest('.sl-related-posts'); if(rp2) rp2.style.display='none'; return; }
        grid.innerHTML=entries.map(function(e){
          var l=(e.link||[]).filter(function(l){ return l.rel==='alternate'; })[0];
          var url=esc(l?l.href:'#');
          var title=esc((e.title||{}).$t||'');
          var cat=esc(((e.category||[])[0]||{}).term||'');
          var raw=(e.media$thumbnail||{}).url||'';
          var thumb=esc(raw?raw.replace(/\/s[\d]+-c(\/|$)/,'/w400-h225-c/'):'[[PLACEHOLDER_IMG]]');
          var date=(e.published||{}).$t?new Date(e.published.$t).toLocaleDateString('pt-BR'):'';
          return '<div class="col"><article class="news-card d-flex flex-column h-100">'
            +'<a href="'+url+'" class="overflow-hidden d-block"><img src="'+thumb+'" alt="'+title+'" loading="lazy" class="news-card-img w-100"/></a>'
            +'<div class="p-3 d-flex flex-column flex-grow-1">'
            +(cat?'<span class="blog-featured-tag d-inline-block mb-1" style="font-size:.68rem;padding:2px 8px!important;">'+cat+'</span>':'')
            +'<h4 class="h6 fw-bold mb-2"><a class="text-body text-decoration-none" href="'+url+'">'+title+'</a></h4>'
            +'<div class="mt-auto small text-muted"><i class="bi bi-clock me-1"></i>'+esc(date)+'</div>'
            +'</div></article></div>';
        }).join('');
      })
      .catch(function(){ var rp3=grid.closest('.sl-related-posts'); if(rp3) rp3.style.display='none'; });
  })();
  //




